return [
  { platform: 'meta', campaign_id: 'fixture-underpace', spend_cents: 20000, revenue_cents: 25000, budget_cents: 100000, elapsed_bps: 5000, baseline_roas_bps: 20000, attribution_bps: 9500 },
  { platform: 'google', campaign_id: 'fixture-attribution', spend_cents: 40000, revenue_cents: 90000, budget_cents: 80000, elapsed_bps: 5000, baseline_roas_bps: 21000, attribution_bps: 5500 },
  { platform: 'meta', campaign_id: 'fixture-monitor', spend_cents: 50000, revenue_cents: 110000, budget_cents: 100000, elapsed_bps: 5000, baseline_roas_bps: 20000, attribution_bps: 10000 },
  { platform: 'google', campaign_id: 'fixture-malformed', spend_cents: '40000', revenue_cents: 90000, budget_cents: 80000, elapsed_bps: 5000, baseline_roas_bps: 21000, attribution_bps: 9500 },
].map(json => ({ json }));

const limits = {
  spend_cents: [0, 1000000000], revenue_cents: [0, 1000000000],
  budget_cents: [1, 1000000000], elapsed_bps: [1, 10000],
  baseline_roas_bps: [0, 1000000], attribution_bps: [0, 10000],
};
return $input.all().map(({ json: row }) => {
  const invalid = [];
  if (!['meta', 'google'].includes(row.platform)) invalid.push('platform');
  if (typeof row.campaign_id !== 'string' || !/^fixture-[a-z0-9-]{1,60}$/.test(row.campaign_id)) invalid.push('campaign_id');
  const metrics = {};
  for (const [key, [min, max]] of Object.entries(limits)) {
    const value = row[key];
    if (!Number.isSafeInteger(value) || value < min || value > max) {
      invalid.push(key);
    } else {
      metrics[key] = value;
    }
  }
  return { json: {
    platform: invalid.includes('platform') ? null : row.platform,
    campaign_id: invalid.includes('campaign_id') ? null : row.campaign_id,
    invalid_fields: invalid,
    metrics: invalid.length ? null : metrics,
  } };
});

return $input.all().map(({ json: row }) => {
  const m = row.metrics;
  const reasons = [];
  let action = 'monitor';
  if (row.invalid_fields.length) {
    action = 'data_quality_review';
    reasons.push('invalid_snapshot');
  } else if (m.attribution_bps < 8000) {
    action = 'data_quality_review';
    reasons.push('attribution_incomplete');
  } else {
    // Integer cross-products stay below Number.MAX_SAFE_INTEGER at the declared bounds.
    if (m.spend_cents * 40000 < m.budget_cents * m.elapsed_bps * 3) {
      reasons.push('under_pacing');
    }
    if (m.spend_cents > 0 && m.revenue_cents * 100000 < m.spend_cents * m.baseline_roas_bps * 7) {
      reasons.push('roas_below_baseline');
    }
    if (reasons.length) action = 'optimization_review';
  }
  return { json: {
    ...row, action, reasons,
    roas: m && m.spend_cents > 0 ? m.revenue_cents / m.spend_cents : null,
    pacing: m ? (m.spend_cents * 10000) / (m.budget_cents * m.elapsed_bps) : null,
    requires_human_review: action !== 'monitor',
    automatic_budget_change_allowed: false,
  } };
});
